   152	/** The hold's progress from 0 to 1, for the bar (0 without a hold). */
   153	export function holdProgress(objectives: ObjectivesSnapshot | undefined): number {
   154	  if (objectives === undefined || objectives.channel === "" || objectives.channelTotal === 0) return 0;
   155	  return Math.min(1, objectives.channelHeld / objectives.channelTotal);
   156	}
   157	
   158	/** The last finished hold: "Collected the Sun rubbing", or why it came to nothing. */
   159	export function resultLine(model: Pick<HudModel, "objectives">): HudLine {
   160	  const result = model.objectives?.channelResult ?? "";
   161	  if (result === "") return { text: "", state: "none" };
   162	  const [kind, detail] = result.split(":");
   163	  if (kind === "collected") return { text: `Collected the ${typeName(detail!)} rubbing`, state: result };
   164	  if (kind === "claimed") return { text: `Claimed the ${typeName(detail!)} rubbing from the cache`, state: result };
   165	  return { text: "Someone else took that rubbing first", state: result };
   166	}
   167	
   168	/**
   169	 * The last duel's settlement (§4, §11), from this player's side: what was stolen and the gold that moved. The loser
   170	 * sees what was taken; both see the gold change; a draw moves nothing.
   171	 */
   172	export function settlementLine(model: Pick<HudModel, "objectives">): HudLine {
   173	  const objectives = model.objectives;
   174	  if (objectives === undefined || objectives.settledRole === "") return { text: "", state: "none" };
   175	  const gold = Math.abs(objectives.goldChange);
   176	  const stolen = objectives.stolen === "" ? "" : typeName(objectives.stolen);
   177	  switch (objectives.settledRole) {
   178	    case "winner":
   179	      if (stolen === "") return { text: gold > 0 ? `Duel won: +${gold} gold (they held nothing you lack)` : "Duel won: nothing to take", state: "winner" };
